-- M6 contract DDL v1. Cross-owner UUIDs are references, never foreign keys.
SET LOCAL timezone = 'UTC';
CREATE TABLE sla.calendars (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), code text NOT NULL, calendar_version integer NOT NULL CHECK(calendar_version>0), timezone text NOT NULL CHECK(timezone='Asia/Jakarta'), work_days integer[] NOT NULL, work_start time NOT NULL, work_end time NOT NULL, CHECK(work_end>work_start), UNIQUE(code,calendar_version));
GRANT SELECT, INSERT, UPDATE ON sla.calendars TO helpdesk_m6;
CREATE TABLE sla.holidays (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), calendar_id uuid NOT NULL REFERENCES sla.calendars(id), holiday date NOT NULL, label text NOT NULL, UNIQUE(calendar_id,holiday));
GRANT SELECT, INSERT, UPDATE ON sla.holidays TO helpdesk_m6;
CREATE TABLE sla.targets (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), service_id uuid NOT NULL, calendar_id uuid NOT NULL REFERENCES sla.calendars(id), policy_version integer NOT NULL CHECK(policy_version>0), stage text NOT NULL, target_minutes integer NOT NULL CHECK(target_minutes>0));
GRANT SELECT, INSERT, UPDATE ON sla.targets TO helpdesk_m6;
CREATE TABLE sla.clock_projection (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL UNIQUE, source_version bigint NOT NULL CHECK(source_version>0), accepted_at timestamptz NOT NULL, due_at timestamptz NOT NULL, gross_seconds bigint NOT NULL CHECK(gross_seconds>=0), net_seconds bigint NOT NULL CHECK(net_seconds>=0 AND net_seconds<=gross_seconds), policy_version integer NOT NULL CHECK(policy_version>0));
GRANT SELECT, INSERT, UPDATE ON sla.clock_projection TO helpdesk_m6;
CREATE TABLE sla.idempotency_records (actor_scope text NOT NULL, command text NOT NULL, target text NOT NULL, key text NOT NULL CHECK(length(key) BETWEEN 16 AND 128), payload_digest bytea NOT NULL CHECK(octet_length(payload_digest)=32), response_status integer NOT NULL CHECK(response_status BETWEEN 200 AND 299), response_body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, PRIMARY KEY(actor_scope,command,target,key));
CREATE TABLE sla.outbox (event_id uuid PRIMARY KEY, event_type text NOT NULL, schema_version integer NOT NULL CHECK(schema_version>0), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), occurred_at timestamptz NOT NULL, correlation_id uuid NOT NULL, payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'), digest bytea NOT NULL CHECK(octet_length(digest)=32));
CREATE TABLE sla.outbox_delivery (event_id uuid NOT NULL REFERENCES sla.outbox(event_id), consumer_id text NOT NULL CHECK(consumer_id ~ '^M[1-9]$'), state text NOT NULL CHECK(state IN ('PENDING','LEASED','ACKED','DEAD_LETTER')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), lease_until timestamptz, acked_at timestamptz, last_error_code text, PRIMARY KEY(event_id,consumer_id), CHECK((state='ACKED')=(acked_at IS NOT NULL)));
CREATE TABLE sla.inbox (consumer_id text NOT NULL, event_id uuid NOT NULL, digest bytea NOT NULL CHECK(octet_length(digest)=32), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer_id,event_id));
CREATE TABLE sla.audit_intents (id uuid PRIMARY KEY, actor_id uuid NOT NULL, action text NOT NULL, object_id uuid NOT NULL, scope text NOT NULL, reason text NOT NULL, outcome text NOT NULL, correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON sla.idempotency_records, sla.outbox, sla.inbox, sla.audit_intents TO helpdesk_m6;
GRANT SELECT, INSERT, UPDATE ON sla.outbox_delivery TO helpdesk_m6;
CREATE INDEX ON sla.outbox_delivery (state, lease_until, event_id) WHERE state<>'ACKED';
REVOKE ALL ON ALL TABLES IN SCHEMA sla FROM PUBLIC;
